<?php require __DIR__.'/../bootstrap.php';admin_only();verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$role=$_POST['role'];$status=$_POST['status'];$pdo->prepare('UPDATE users SET role=?,status=? WHERE id=?')->execute([$role,$status,$id]);flash('ok','کاربر بروزرسانی شد.');redirect('admin/users.php');}$users=$pdo->query('SELECT * FROM users ORDER BY id DESC')->fetchAll();$title='کاربران';require __DIR__.'/../partials/header.php';?><h1>کاربران</h1><div class="panel table-wrap"><table class="table"><tr><th>نام</th><th>ایمیل</th><th>نقش</th><th>وضعیت</th><th>ثبت‌نام</th><th>ذخیره</th></tr><?php foreach($users as $u): ?><tr><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$u['id']?>"><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><select name="role"><option value="customer" <?=$u['role']==='customer'?'selected':''?>>customer</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>admin</option><option value="superadmin" <?=$u['role']==='superadmin'?'selected':''?>>superadmin</option></select></td><td><select name="status"><option value="active" <?=$u['status']==='active'?'selected':''?>>active</option><option value="blocked" <?=$u['status']==='blocked'?'selected':''?>>blocked</option></select></td><td><?=$u['created_at']?></td><td><button class="btn small">ذخیره</button></td></form></tr><?php endforeach;?></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
